package com.etic.licensecontrol.common;
import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/lookups") public class LookupController {private final CrudService c;LookupController(CrudService c){this.c=c;}@GetMapping("/{type:users|systems|user-types|licensed-systems|user-licensed-systems|devices}")List<Map<String,Object>>get(@PathVariable String type,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="0")int page){String sql=switch(type){case"users"->"SELECT Id_User id,CONCAT(TRIM(CONCAT_WS(' ',First_Name,Last_Name,Second_Last_Name)),' (',Username,')') label FROM users WHERE Is_Active=TRUE ORDER BY Username";case"systems"->"SELECT Id_System id,Name label FROM systems WHERE Is_Active=TRUE ORDER BY Name";case"user-types"->"SELECT Id_User_Type id,Name label FROM user_types WHERE Is_Active=TRUE ORDER BY Name";case"licensed-systems","user-licensed-systems"->"SELECT s.Id_System id,s.Name label,sl.Licensing_Mode,s.Status FROM systems s JOIN system_licensing sl ON sl.Id_System=s.Id_System WHERE s.Is_Active=TRUE AND s.Status=\'ACTIVE\' AND sl.Is_Active=TRUE AND s.System_Type='ANDROID' "+("user-licensed-systems".equals(type)?"AND sl.Licensing_Mode='USER_DEVICE' ":"")+"ORDER BY s.Name";default->"SELECT Id_Device id,COALESCE(NULLIF(Display_Name,''),'Sin nombre') label,Status FROM licensed_devices WHERE Is_Active=TRUE ORDER BY Registered_At DESC";};return c.db().queryForList("SELECT * FROM ("+sql+") lookup WHERE label LIKE :search ORDER BY label LIMIT 100 OFFSET :offset",Map.of("search","%"+search+"%","offset",Math.max(page,0)*100));}}
